Additionally, the number of participants and participant-days are counted for each dosimeter position.


::: {.cell}

```{.r .cell-code .hidden}
#| label: count-positions

datasets <- lst(BAUA, FUSPCEU, IZTECH, MPI, KNUST, RISE, THUAS, TUM, UCR)

summary_tbl <- datasets |>
  imap(~ .x |>
         ungroup() |>
         mutate(date = as_date(Datetime)) |>
         group_by(position) |>
         summarise(
           participants     = n_distinct(Id),
           participant_days = n_distinct(Id, date),
           .groups = "drop"
         ) |>
         mutate(dataset = .y, .before = 1)) |>
  list_rbind() |>
  # Format table contents
  pivot_wider(
    names_from  = position,
    values_from = c(participants, participant_days),
    values_fill = 0,
    names_glue  = "{position}_{.value}"
  ) |>
  select(dataset,
         starts_with("h_"),
         starts_with("c_"),
         starts_with("w_"))

# Calculate totals for each column
summary_tbl <- summary_tbl |>
  bind_rows(
    summary_tbl |>
      summarise(across(where(is.numeric), sum)) |>
      mutate(dataset = "Total")
  )

# Render table
summary_tbl |>
  gt(rowname_col = "dataset") |>
  tab_spanner(label = "Head (glasses)", columns = starts_with("h_")) |>
  tab_spanner(label = "Chest", columns = starts_with("c_")) |>
  tab_spanner(label = "Wrist", columns = starts_with("w_")) |>
  cols_label(
    ends_with("_participants")     ~ "Participants",
    ends_with("_participant_days") ~ "Participant-days"
  ) |>
  tab_style(
    style = cell_text(weight = "bold"),
    locations = list(
      cells_stub(),
      cells_column_labels(),
      cells_column_spanners()
    )
  ) |>
  tab_style(
    style = list(cell_text(weight = "bold"), cell_fill(color = "#f2f2f2")),
    locations = list(
      cells_stub(rows = "Total"),
      cells_body(rows = nrow(summary_tbl))
    )
  ) |>
  tab_header(
    title = "Trimmed by trial period"
  )
```

