p_abs <- hist_data |>
  filter(scale_type == "absdif") |>
  ggplot(aes(x = value, fill = position, color = position)) +
  geom_histogram(binwidth = 50, alpha = 0.85) +
  facet_wrap(~ position) +
  theme_cowplot() +
  scale_fill_manual(values = c(Chest = pos_colors[["chest"]],
                               Wrist = pos_colors[["wrist"]])) +
  scale_color_manual(values = c(Chest = pos_colors[["chest"]],
                                Wrist = pos_colors[["wrist"]])) +
  scale_y_continuous(labels = label_comma()) +
  coord_cartesian(xlim = c(-2500, 2500)) +
  guides(fill = "none", color = "none") +
  labs(x = "Absolute difference [m-EDI]", y = "Count (n)") +
  theme(panel.spacing = unit(1, "lines"))

