  scale_y_continuous(labels = label_comma()) +
  guides(fill = "none") +
  labs(x = "Logarithmic difference [log10 m-EDI]", y = "Count (n)") +
  theme(panel.spacing = unit(1, "lines"),
        strip.background = element_blank(),
        strip.text = element_blank())

p_abs / p_log
